def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]

    # Identify the orientation of the colored guide lines.
    horizontal = all(all(grid[r][c] == grid[r][0] for c in range(w))
                     for r in range(h) if any(grid[r]))
    if horizontal:
        offsets = {r for r, _, _ in cells}
        period = len(offsets)
        pattern = {}
        for r, _, v in cells:
            pattern[r % period] = v
        return [[pattern[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal guide lines run down-right; each line has constant column-row.
    offsets = {c - r for r, c, _ in cells}
    period = len(offsets)
    pattern = {}
    for r, c, v in cells:
        pattern[(c - r) % period] = v
    return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
